INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 100, 10142, "エリコ", 1, 24, 100, "2030/12/17 14:59:59", 129901, 7, "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス", 10.85);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 101, 10142, "エリコ", 1, 24, 101, "2030/12/17 14:59:59", 129901, 2, "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス", 11.15);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 102, 10142, "エリコ", 7, 24, 102, "2030/12/17 14:59:59", 129901, 5, "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…", 6.4);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 103, 10142, "エリコ", 3, 24, 103, "2030/12/17 14:59:59", 129901, 3, "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？", 0.0);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 104, 10142, "エリコ", 2, 24, 104, "2030/12/17 14:59:59", 129901, 8, "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス", 2.43);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 105, 10142, "エリコ", 4, 24, 105, "2030/12/17 14:59:59", 129901, 3, "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？", 9.08);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 106, 10142, "エリコ", 6, 24, 106, "2030/12/17 14:59:59", 129901, 6, "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので", 0.0);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 107, 10142, "エリコ", 3, 24, 107, "2030/12/17 14:59:59", 129901, 8, "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス", 10.6);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 108, 10142, "エリコ", 6, 24, 108, "2030/12/17 14:59:59", 129901, 4, "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね", 7.54);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 109, 10142, "エリコ", 2, 24, 109, "2030/12/17 14:59:59", 129901, 7, "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…", 11.5);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 110, 10142, "エリコ", 2, 24, 110, "2030/12/17 14:59:59", 129901, 1, "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう", 8.83);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 111, 10142, "エリコ", 1, 24, 111, "2030/12/17 14:59:59", 129901, 2, "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね", 6.68);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 112, 10142, "エリコ", 6, 24, 112, "2030/12/17 14:59:59", 129901, 2, "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい", 8.8);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 113, 10142, "エリコ", 2, 24, 113, "2030/12/17 14:59:59", 129901, 1, "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから", 8.9);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 114, 10142, "エリコ", 2, 24, 114, "2030/12/17 14:59:59", 129901, 5, "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！", 3.7);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 200, 10142, "マコト", 1, 24, 200, "2030/12/17 14:59:59", 129801, 2, "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ", 7.6);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 201, 10142, "マコト", 2, 24, 201, "2030/12/17 14:59:59", 129801, 1, "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ", 2.25);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 202, 10142, "マコト", 2, 24, 202, "2030/12/17 14:59:59", 129801, 1, "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ", 3.28);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 203, 10142, "マコト", 4, 24, 203, "2030/12/17 14:59:59", 129801, 1, "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！", 2.98);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 204, 10142, "マコト", 4, 24, 204, "2030/12/17 14:59:59", 129801, 1, "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！", 3.0);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 205, 10142, "マコト", 1, 24, 205, "2030/12/17 14:59:59", 129801, 2, "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！", 10.3);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 206, 10142, "マコト", 6, 24, 206, "2030/12/17 14:59:59", 129801, 1, "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！", 2.93);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 207, 10142, "マコト", 3, 24, 207, "2030/12/17 14:59:59", 129801, 1, "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！", 9.3);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 208, 10142, "マコト", 4, 24, 208, "2030/12/17 14:59:59", 129801, 1, "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ", 6.9);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 209, 10142, "マコト", 2, 24, 209, "2030/12/17 14:59:59", 129801, 2, "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！", 0.0);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 210, 10142, "マコト", 1, 24, 210, "2030/12/17 14:59:59", 129801, 2, "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ", 5.95);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 211, 10142, "マコト", 2, 24, 211, "2030/12/17 14:59:59", 129801, 1, "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…", 6.73);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 212, 10142, "マコト", 2, 24, 212, "2030/12/17 14:59:59", 129801, 2, "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！", 0.0);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 213, 10142, "マコト", 1, 24, 213, "2030/12/17 14:59:59", 129801, 2, "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ", 6.65);
INSERT INTO `v1_0ddaf0975825562526a933d92414f08ad99380825846c4b431c4590067ad88c3` VALUES (0.0, 0.0, "2024/03/31 12:00:00", 214, 10142, "マコト", 6, 24, 214, "2030/12/17 14:59:59", 129801, 1, "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！", 3.05);
